from eth_abi import decode_abi
from eth_utils import remove_0x_prefix, to_checksum_address


def generate_solidity_test_with_checksum(input_data: str, caller: str, governor: str, block_number: int, output_path: str):
    clean_input = remove_0x_prefix(input_data)[8:]
    data_body = bytes.fromhex(clean_input)

    types = ["address[]", "uint256[]", "bytes[]", "bytes32"]
    targets, values, calldatas, description_hash = decode_abi(types, data_body)

    # Apply checksum to addresses
    caller = to_checksum_address(caller)
    governor = to_checksum_address(governor)
    targets = [to_checksum_address(addr) for addr in targets]

    code_lines = []
    code_lines.append(f"address[] memory targets = new address[]({len(targets)});")
    for i, addr in enumerate(targets):
        code_lines.append(f'targets[{i}] = {addr};')

    code_lines.append(f"uint256[] memory values = new uint256[]({len(values)});")
    for i, val in enumerate(values):
        code_lines.append(f'values[{i}] = {val};')

    code_lines.append(f"bytes[] memory calldatas = new bytes[]({len(calldatas)});")
    for i, calldata in enumerate(calldatas):
        hexdata = "hex\"" + calldata.hex() + "\""
        code_lines.append(f'calldatas[{i}] = {hexdata};')

    code_lines.append(f"bytes32 descriptionHash = 0x{description_hash.hex()};")
    formatted_code = "\n        ".join(code_lines)

    sol_template = f"""// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";

interface IGovernor {{
    function execute(
        address[] calldata targets,
        uint256[] calldata values,
        bytes[] calldata calldatas,
        bytes32 descriptionHash
    ) external;
}}

contract SimulateGovernorTx is Test {{
    address constant CALLER = {caller};
    address constant GOVERNOR = {governor};

    function setUp() public {{
        vm.createSelectFork("mainnet", {block_number-1});
    }}

    function testSimulateExecuteTx() public {{
        {formatted_code}
        vm.prank(CALLER);
        IGovernor(GOVERNOR).execute(targets, values, calldatas, descriptionHash);
    }}
}}
"""
    with open(output_path, "w") as f:
        f.write(sol_template)

    print(f"✅ Solidity test written to {output_path}")


# === Example Usage ===
if __name__ == "__main__":
    input_data = ""  # Replace with full calldata
    caller = "0x5c04e7808455ee0e22c2773328c151d0dd79dc62"
    governor = "0x309a862bbc1a00e45506cb8a802d1ff10004c8c0"
    block_number = 21860333
    output_path = "test/SimulateGovernorTx.t.sol"

    generate_solidity_test_with_checksum(input_data, caller, governor, block_number, output_path)